+func (rb *AppExecLinkReparseBuffer) Path() string {
+	UTF16ToStringPosition := func(s []uint16) (string, int) {
+		for i, v := range s {
+			if v == 0 {
+				s = s[0:i]
+				return string(utf16.Decode(s)), i
+			}
+		}
+		return "", 0
+	}
